package com.fossferous.aldarinchests;

import java.awt.Color;
import net.runelite.client.config.Alpha;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Notification;
import net.runelite.client.config.Range;

@ConfigGroup(AldarinChestsConfig.GROUP)
public interface AldarinChestsConfig extends Config
{
	String GROUP = "aldarinvillachests";

	@Alpha
	@ConfigItem(
		keyName = "readyColor",
		name = "Ready colour",
		description = "Colour of a chest you can click now",
		position = 1
	)
	default Color readyColor()
	{
		return new Color(0, 255, 0, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "busyColor",
		name = "Picking colour",
		description = "Colour of the chest while your current attempt is still running",
		position = 2
	)
	default Color busyColor()
	{
		return new Color(255, 165, 0, 255);
	}

	@Alpha
	@ConfigItem(
		keyName = "openColor",
		name = "Open colour",
		description = "Colour of a chest that was just looted and has not closed again yet",
		position = 3
	)
	default Color openColor()
	{
		return new Color(255, 0, 0, 255);
	}

	@ConfigItem(
		keyName = "showCountdown",
		name = "Tick countdown",
		description = "Show the game ticks left before the chest is ready",
		position = 4
	)
	default boolean showCountdown()
	{
		return true;
	}

	@ConfigItem(
		keyName = "fillClickbox",
		name = "Fill clickbox",
		description = "Also tint the chest's clickbox, not only its outline",
		position = 5
	)
	default boolean fillClickbox()
	{
		return true;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "outlineWidth",
		name = "Outline width",
		description = "Width of the chest outline in pixels",
		position = 6
	)
	default int outlineWidth()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "readyNotification",
		name = "Ready notification",
		description = "Notify when the chest you are picking becomes ready to click again",
		position = 7
	)
	default Notification readyNotification()
	{
		return Notification.OFF;
	}

	@ConfigItem(
		keyName = "trapNotification",
		name = "Trap notification",
		description = "Notify when a trap has teleported you out, so you head back up the stairs",
		position = 8
	)
	default Notification trapNotification()
	{
		return Notification.OFF;
	}
}

