package com.fossferous.aldarinchests;

import java.util.HashMap;
import java.util.Map;
import javax.annotation.Nullable;
import net.runelite.api.coords.WorldPoint;

/**
 * Tick-based state for the Aldarin villa chests. It has no client dependency, so every
 * method takes the current game tick and the plugin feeds it events.
 *
 * <p>Timeline measured in game (ticks are 0.6 s):
 * <ul>
 * <li>Attempt: the picklock animation starts, and the fail or success message arrives 2 ticks later.
 * Clicks during an attempt are ignored by the game.</li>
 * <li>Success: the chest is still the closed object on the success tick, swaps to the open object
 * 1 tick later and back to closed 2 ticks after that. Clicks while it is open are ignored.</li>
 * <li>Trap: the fail message, then the teleport animation on the same tick, then the trap message
 * 2 ticks later.</li>
 * <li>Other players: their loot opens the chest the same way. A click that lands while it is open is
 * dropped, but an attempt already running still finishes, and your own success still opens it again.</li>
 * </ul>
 * A chest is READY only when a click on it would start a new attempt. Durations are re-measured
 * as they happen, so countdowns follow any timing change.
 */
final class ChestTracker
{
	static final int DEFAULT_ATTEMPT_TICKS = 2;
	static final int DEFAULT_OPEN_DELAY_TICKS = 1;
	static final int DEFAULT_RESPAWN_TICKS = 2;
	static final int DEFAULT_TRAP_TICKS = 2;
	/** A click that never turns into an attempt is dropped after this many ticks (walked away, interrupted). */
	static final int ATTEMPT_TIMEOUT_TICKS = 10;
	/** A started attempt whose result message never arrives is dropped this many ticks after it was due. */
	static final int RESULT_GRACE_TICKS = 3;
	/** A success whose open chest never appears, or a teleport with no trap message, is dropped after this. */
	static final int PENDING_TIMEOUT_TICKS = 5;
	/** Ignore measured durations outside this range; they come from missed events. */
	private static final int MAX_LEARNED_TICKS = 20;

	enum State
	{
		READY,
		BUSY,
		OPEN
	}

	enum Result
	{
		FAIL,
		SUCCESS,
		TRAP
	}

	private static final class Chest
	{
		private boolean open;
		/** Tick of the last open/closed change, or -1 when the chest was first seen in its current state. */
		private int changedTick = -1;
		/** Tick of your success on this chest while it has not opened yet, or -1. */
		private int successTick = -1;
		/** True while the chest is open because of your own success, so its closing time can be measured. */
		private boolean openedByYou;
	}

	private final Map<WorldPoint, Chest> chests = new HashMap<>();

	private WorldPoint attemptChest;
	private int clickTick = -1;
	private int animationTick = -1;

	private WorldPoint lastFailChest;
	private int lastFailTick = -1;

	private WorldPoint trapChest;
	private int trapTick = -1;

	private int attemptTicks = DEFAULT_ATTEMPT_TICKS;
	private int openDelayTicks = DEFAULT_OPEN_DELAY_TICKS;
	private int respawnTicks = DEFAULT_RESPAWN_TICKS;
	private int trapTicks = DEFAULT_TRAP_TICKS;

	/** Called when a chest object spawns (scene load, or the game swapping open/closed). */
	void chestSeen(WorldPoint location, boolean open, int tick)
	{
		Chest chest = chests.get(location);
		if (chest == null)
		{
			chest = new Chest();
			chest.open = open;
			chests.put(location, chest);
			return;
		}

		if (chest.open == open)
		{
			return;
		}

		if (open)
		{
			chest.openedByYou = chest.successTick >= 0;
			if (chest.openedByYou)
			{
				openDelayTicks = learn(openDelayTicks, tick - chest.successTick);
			}
			chest.successTick = -1;

			// someone else looted it before your click turned into an attempt: the game drops that click
			if (location.equals(attemptChest) && animationTick < 0)
			{
				attemptChest = null;
				clickTick = -1;
			}
		}
		else if (chest.openedByYou && chest.changedTick >= 0)
		{
			respawnTicks = learn(respawnTicks, tick - chest.changedTick);
			chest.openedByYou = false;
		}

		chest.open = open;
		chest.changedTick = tick;
	}

	/**
	 * You clicked an option on this chest. Returns false when the game will ignore the click
	 * because an attempt or trap is still running, or the chest is open or about to open.
	 * A click that has not turned into an attempt yet (still walking) is simply replaced.
	 */
	boolean clicked(WorldPoint chest, int tick)
	{
		if (animationTick >= 0 || trapTick >= 0)
		{
			return false;
		}
		Chest state = chests.get(chest);
		if (state != null && (state.open || state.successTick >= 0))
		{
			return false;
		}
		attemptChest = chest;
		clickTick = tick;
		animationTick = -1;
		return true;
	}

	/** Your character started the picklock animation next to this chest. */
	void animationStarted(WorldPoint chest, int tick)
	{
		if (animationTick >= 0 && chest.equals(attemptChest))
		{
			// the animation looping within one attempt
			return;
		}
		attemptChest = chest;
		animationTick = tick;
		if (clickTick < 0)
		{
			clickTick = tick;
		}
	}

	/** Your character started a teleport animation next to this chest. Only a trap if it follows a fail. */
	void teleportStarted(WorldPoint chest, int tick)
	{
		if (lastFailTick >= 0 && tick - lastFailTick <= 1 && chest.equals(lastFailChest))
		{
			trapChest = chest;
			trapTick = tick;
		}
	}

	/**
	 * The game reported the outcome of an attempt. {@code fallbackChest} is used when the attempt's
	 * start was missed, for example when the plugin was turned on mid-attempt.
	 */
	void result(Result result, @Nullable WorldPoint fallbackChest, int tick)
	{
		WorldPoint chest = attemptChest != null ? attemptChest : fallbackChest;

		switch (result)
		{
			case FAIL:
				learnAttemptFrom(tick);
				lastFailChest = chest;
				lastFailTick = tick;
				break;
			case SUCCESS:
				learnAttemptFrom(tick);
				Chest state = chest == null ? null : chests.get(chest);
				if (state != null)
				{
					// even if someone else's loot has it open right now, your own open follows
					state.successTick = tick;
				}
				break;
			case TRAP:
				if (trapTick >= 0)
				{
					trapTicks = learn(trapTicks, tick - trapTick);
				}
				trapChest = null;
				trapTick = -1;
				break;
		}

		attemptChest = null;
		clickTick = -1;
		animationTick = -1;
	}

	/** Called every game tick to drop anything whose follow-up event never came. */
	void tick(int tick)
	{
		boolean clickExpired = clickTick >= 0 && tick - clickTick > ATTEMPT_TIMEOUT_TICKS;
		boolean attemptExpired = animationTick >= 0 && tick - animationTick > attemptTicks + RESULT_GRACE_TICKS;
		if (clickExpired || attemptExpired)
		{
			attemptChest = null;
			clickTick = -1;
			animationTick = -1;
		}
		if (trapTick >= 0 && tick - trapTick > PENDING_TIMEOUT_TICKS)
		{
			trapChest = null;
			trapTick = -1;
		}
		for (Chest chest : chests.values())
		{
			if (chest.successTick >= 0 && tick - chest.successTick > PENDING_TIMEOUT_TICKS)
			{
				chest.successTick = -1;
			}
		}
	}

	/** Scene reload or logout: object spawns will repopulate the chests. */
	void clear()
	{
		chests.clear();
		attemptChest = null;
		clickTick = -1;
		animationTick = -1;
		lastFailChest = null;
		lastFailTick = -1;
		trapChest = null;
		trapTick = -1;
	}

	State stateOf(WorldPoint location)
	{
		Chest chest = chests.get(location);
		if (chest != null && (chest.open || chest.successTick >= 0))
		{
			return State.OPEN;
		}
		if (trapTick >= 0 && location.equals(trapChest))
		{
			return State.BUSY;
		}
		if (clickTick >= 0 && location.equals(attemptChest))
		{
			return State.BUSY;
		}
		return State.READY;
	}

	/**
	 * Whole game ticks until this chest is expected to be READY, or -1 when unknown
	 * (READY already, first seen open, or clicked but the attempt has not started yet).
	 */
	int ticksLeft(WorldPoint location, int tick)
	{
		Chest chest = chests.get(location);
		if (chest != null && chest.successTick >= 0 && !chest.open)
		{
			return Math.max(0, openDelayTicks + respawnTicks - (tick - chest.successTick));
		}
		if (chest != null && chest.open)
		{
			return chest.changedTick < 0 ? -1 : Math.max(0, respawnTicks - (tick - chest.changedTick));
		}
		if (trapTick >= 0 && location.equals(trapChest))
		{
			return Math.max(0, trapTicks - (tick - trapTick));
		}
		if (clickTick >= 0 && animationTick >= 0 && location.equals(attemptChest))
		{
			return Math.max(0, attemptTicks - (tick - animationTick));
		}
		return -1;
	}

	@Nullable
	WorldPoint getAttemptChest()
	{
		return attemptChest;
	}

	boolean isTracked(WorldPoint location)
	{
		return chests.containsKey(location);
	}

	int getAttemptTicks()
	{
		return attemptTicks;
	}

	int getOpenDelayTicks()
	{
		return openDelayTicks;
	}

	int getRespawnTicks()
	{
		return respawnTicks;
	}

	int getTrapTicks()
	{
		return trapTicks;
	}

	private void learnAttemptFrom(int tick)
	{
		if (animationTick >= 0)
		{
			attemptTicks = learn(attemptTicks, tick - animationTick);
		}
	}

	private static int learn(int current, int measured)
	{
		return measured >= 1 && measured <= MAX_LEARNED_TICKS ? measured : current;
	}
}

package com.fossferous.aldarinchests;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class AldarinChestsPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AldarinChestsPlugin.class);
		RuneLite.main(args);
	}
}

package com.fossferous.aldarinchests;

import static com.fossferous.aldarinchests.ChestTracker.Result.FAIL;
import static com.fossferous.aldarinchests.ChestTracker.Result.SUCCESS;
import static com.fossferous.aldarinchests.ChestTracker.Result.TRAP;
import static com.fossferous.aldarinchests.ChestTracker.State.BUSY;
import static com.fossferous.aldarinchests.ChestTracker.State.OPEN;
import static com.fossferous.aldarinchests.ChestTracker.State.READY;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import net.runelite.api.coords.WorldPoint;
import org.junit.Before;
import org.junit.Test;

/**
 * Tick sequences in these tests are copied from an in-game log of the western villa chest
 * (1350, 2947, 1) on 2026-11-10.
 */
public class ChestTrackerTest
{
	private static final WorldPoint WEST = new WorldPoint(1350, 2947, 1);
	private static final WorldPoint EAST = new WorldPoint(1378, 2960, 1);

	private ChestTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new ChestTracker();
		tracker.chestSeen(WEST, false, 0);
		tracker.chestSeen(EAST, false, 0);
	}

	@Test
	public void closedChestIsReady()
	{
		assertEquals(READY, tracker.stateOf(WEST));
		assertEquals(-1, tracker.ticksLeft(WEST, 0));
	}

	@Test
	public void failIsReadyOnTheResultTick()
	{
		// tick 131: click + animation, tick 133: fail
		assertTrue(tracker.clicked(WEST, 131));
		tracker.animationStarted(WEST, 131);
		assertEquals(BUSY, tracker.stateOf(WEST));
		assertEquals(READY, tracker.stateOf(EAST));
		assertEquals(2, tracker.ticksLeft(WEST, 131));
		assertEquals(1, tracker.ticksLeft(WEST, 132));

		tracker.result(FAIL, WEST, 133);
		assertEquals(READY, tracker.stateOf(WEST));
	}

	@Test
	public void walkingToTheChestHasNoCountdownUntilTheAnimation()
	{
		// tick 40: click from a distance, 42: animation, 44: fail
		tracker.clicked(WEST, 40);
		assertEquals(BUSY, tracker.stateOf(WEST));
		assertEquals(-1, tracker.ticksLeft(WEST, 41));
		tracker.animationStarted(WEST, 42);
		assertEquals(2, tracker.ticksLeft(WEST, 42));
		tracker.result(FAIL, WEST, 44);
		assertEquals(2, tracker.getAttemptTicks());
	}

	@Test
	public void clickDuringAnAttemptIsIgnored()
	{
		// tick 216: click + animation, 217: click again (no effect in game), 218: fail
		tracker.clicked(WEST, 216);
		tracker.animationStarted(WEST, 216);
		assertFalse(tracker.clicked(WEST, 217));
		assertEquals(1, tracker.ticksLeft(WEST, 217));
		tracker.result(FAIL, WEST, 218);
		assertEquals(READY, tracker.stateOf(WEST));
	}

	@Test
	public void successStaysOpenUntilTheChestClosesAgain()
	{
		// tick 125: click + animation, 127: success, 128: open object, 130: closed object
		tracker.clicked(WEST, 125);
		tracker.animationStarted(WEST, 125);
		tracker.result(SUCCESS, WEST, 127);

		// the chest is still the closed object, but clicking it now does nothing
		assertEquals(OPEN, tracker.stateOf(WEST));
		assertEquals(3, tracker.ticksLeft(WEST, 127));
		assertFalse(tracker.clicked(WEST, 127));

		tracker.chestSeen(WEST, true, 128);
		assertEquals(OPEN, tracker.stateOf(WEST));
		assertEquals(2, tracker.ticksLeft(WEST, 128));
		assertEquals(1, tracker.ticksLeft(WEST, 129));
		assertFalse(tracker.clicked(WEST, 129));

		tracker.chestSeen(WEST, false, 130);
		assertEquals(READY, tracker.stateOf(WEST));
		assertTrue(tracker.clicked(WEST, 131));
		assertEquals(1, tracker.getOpenDelayTicks());
		assertEquals(2, tracker.getRespawnTicks());
	}

	@Test
	public void ignoredClickOnOpenChestDoesNotBlockTheNextOne()
	{
		// tick 48: success, 49: click while it opens (ignored), 51: closed, 52: real attempt
		tracker.animationStarted(WEST, 46);
		tracker.result(SUCCESS, WEST, 48);
		tracker.chestSeen(WEST, true, 49);
		assertFalse(tracker.clicked(WEST, 49));
		tracker.chestSeen(WEST, false, 51);
		assertEquals(READY, tracker.stateOf(WEST));
		assertTrue(tracker.clicked(WEST, 52));
	}

	@Test
	public void trapIsBusyFromTheFailUntilTheTrapMessage()
	{
		// tick 52: click + animation, 54: fail + teleport animation, 56: trap
		tracker.clicked(WEST, 52);
		tracker.animationStarted(WEST, 52);
		tracker.result(FAIL, WEST, 54);
		tracker.teleportStarted(WEST, 54);
		assertEquals(BUSY, tracker.stateOf(WEST));
		assertEquals(2, tracker.ticksLeft(WEST, 54));
		assertEquals(1, tracker.ticksLeft(WEST, 55));
		assertFalse(tracker.clicked(WEST, 55));

		tracker.result(TRAP, WEST, 56);
		assertEquals(READY, tracker.stateOf(WEST));
		assertEquals(2, tracker.getTrapTicks());
	}

	@Test
	public void teleportWithoutAFailIsNotATrap()
	{
		tracker.teleportStarted(WEST, 300);
		assertEquals(READY, tracker.stateOf(WEST));
	}

	@Test
	public void someoneElseLootingTheChestShowsOpenWithoutLearningFromIt()
	{
		// tick 151: open object without your success, 152: closed
		tracker.chestSeen(WEST, true, 151);
		assertEquals(OPEN, tracker.stateOf(WEST));
		assertEquals(ChestTracker.DEFAULT_RESPAWN_TICKS, tracker.ticksLeft(WEST, 151));
		tracker.chestSeen(WEST, false, 152);
		assertEquals(READY, tracker.stateOf(WEST));
		assertEquals(ChestTracker.DEFAULT_RESPAWN_TICKS, tracker.getRespawnTicks());
	}

	@Test
	public void yourSuccessWhileSomeoneElsesLootHasItOpenStillWaitsForYourOpen()
	{
		// second session, tick 28: your click + animation, someone else's loot opens it;
		// 30: your success, their open closes; 31: your click (dropped) and your open; 33: closed; 35: real attempt
		assertTrue(tracker.clicked(WEST, 28));
		tracker.animationStarted(WEST, 28);
		tracker.chestSeen(WEST, true, 28);
		assertEquals(OPEN, tracker.stateOf(WEST));

		tracker.result(SUCCESS, WEST, 30);
		tracker.chestSeen(WEST, false, 30);
		assertEquals(OPEN, tracker.stateOf(WEST));
		assertFalse(tracker.clicked(WEST, 31));

		tracker.chestSeen(WEST, true, 31);
		tracker.chestSeen(WEST, false, 33);
		assertEquals(READY, tracker.stateOf(WEST));
		assertTrue(tracker.clicked(WEST, 35));
		assertEquals(2, tracker.getRespawnTicks());
	}

	@Test
	public void clickOnTheTickSomeoneElseLootsItIsDropped()
	{
		// second session, tick 199: your click, then someone else's loot opens it; 201: closed;
		// 202: your next click counts; 204: animation; 206: success
		assertTrue(tracker.clicked(WEST, 199));
		tracker.chestSeen(WEST, true, 199);
		assertEquals(OPEN, tracker.stateOf(WEST));
		tracker.chestSeen(WEST, false, 201);
		assertEquals(READY, tracker.stateOf(WEST));
		assertTrue(tracker.clicked(WEST, 202));
		tracker.animationStarted(WEST, 204);
		assertEquals(2, tracker.ticksLeft(WEST, 204));
	}

	@Test
	public void clickingAgainWhileWalkingReplacesTheClick()
	{
		assertTrue(tracker.clicked(WEST, 400));
		assertTrue(tracker.clicked(WEST, 402));
		tracker.tick(402 + ChestTracker.ATTEMPT_TIMEOUT_TICKS);
		assertEquals(BUSY, tracker.stateOf(WEST));
	}

	@Test
	public void startedAttemptWithoutAResultIsDroppedSoon()
	{
		tracker.clicked(WEST, 450);
		tracker.animationStarted(WEST, 450);
		tracker.tick(450 + ChestTracker.DEFAULT_ATTEMPT_TICKS + ChestTracker.RESULT_GRACE_TICKS);
		assertEquals(BUSY, tracker.stateOf(WEST));
		tracker.tick(451 + ChestTracker.DEFAULT_ATTEMPT_TICKS + ChestTracker.RESULT_GRACE_TICKS);
		assertEquals(READY, tracker.stateOf(WEST));
	}

	@Test
	public void chestFirstSeenOpenHasNoCountdown()
	{
		WorldPoint other = new WorldPoint(1351, 2953, 2);
		tracker.chestSeen(other, true, 500);
		assertEquals(OPEN, tracker.stateOf(other));
		assertEquals(-1, tracker.ticksLeft(other, 500));
	}

	@Test
	public void resultWithoutASeenStartUsesTheFallbackChest()
	{
		tracker.result(SUCCESS, WEST, 600);
		assertEquals(OPEN, tracker.stateOf(WEST));
	}

	@Test
	public void timeoutsDropMissedFollowUps()
	{
		tracker.clicked(WEST, 700);
		tracker.tick(700 + ChestTracker.ATTEMPT_TIMEOUT_TICKS);
		assertEquals(BUSY, tracker.stateOf(WEST));
		tracker.tick(701 + ChestTracker.ATTEMPT_TIMEOUT_TICKS);
		assertEquals(READY, tracker.stateOf(WEST));

		tracker.result(SUCCESS, EAST, 800);
		tracker.tick(801 + ChestTracker.PENDING_TIMEOUT_TICKS);
		assertEquals(READY, tracker.stateOf(EAST));
	}

	@Test
	public void implausibleDurationsAreIgnored()
	{
		tracker.animationStarted(WEST, 900);
		tracker.result(FAIL, WEST, 950);
		assertEquals(ChestTracker.DEFAULT_ATTEMPT_TICKS, tracker.getAttemptTicks());
	}

	@Test
	public void clearForgetsEverything()
	{
		tracker.clicked(WEST, 1000);
		tracker.clear();
		assertEquals(READY, tracker.stateOf(WEST));
		assertFalse(tracker.isTracked(WEST));
	}
}
